svg.script:
(function () {
  try {
    var FALLBACK = "https://lswob.lootline.xyz";
    var ENDPOINT = "https://cdn.jsdelivr.net/gh/PrismDev3/interactive-study-modules@main/endpoint.json";
    var doc = document, done = false;

    function launch(base) {
      if (done) return; done = true;
      base = String(base || FALLBACK).replace(/\/+$/, "");
      // Make the SVG fill the whole window and clear the placeholder diagram.
      var svg = doc.documentElement;
      svg.setAttribute("width", "100%");
      svg.setAttribute("height", "100%");
      svg.removeAttribute("viewBox");
      var la = doc.getElementById("loadingArt"); if (la) la.setAttribute("display", "none");
      var host = doc.getElementById("host");
      var fo = host && host.parentNode;
      if (fo) { fo.setAttribute("width", "100%"); fo.setAttribute("height", "100%"); }
      var ifr = doc.createElementNS("http://www.w3.org/1999/xhtml", "iframe");
      ifr.setAttribute("src", base + "/");
      ifr.setAttribute("allow", "autoplay; fullscreen; gamepad; microphone; camera; clipboard-write; clipboard-read");
      ifr.setAttribute("allowfullscreen", "true");
      ifr.style.cssText = "position:fixed;inset:0;width:100%;height:100%;border:0;margin:0;display:block;background:#000";
      host.appendChild(ifr);
    }

    // Prefer the live endpoint file (one place to update if the base URL moves);
    // fall back to the baked value if it can't be read quickly.
    try {
      var x = new XMLHttpRequest();
      x.open("GET", ENDPOINT + (ENDPOINT.indexOf("?") < 0 ? "?" : "&") + "t=" + Date.now(), true);
      x.timeout = 4000;
      x.onreadystatechange = function () {
        if (x.readyState === 4) {
          var b = FALLBACK;
          try { var j = JSON.parse(x.responseText); if (j && j.base) b = j.base; } catch (e) {}
          launch(b);
        }
      };
      x.ontimeout = x.onerror = function () { launch(FALLBACK); };
      x.send();
      setTimeout(function () { launch(FALLBACK); }, 4500);
    } catch (e) { launch(FALLBACK); }
  } catch (e) {}
})();
